// Types of games/chytanka («Читанка-мандрівка»: Ukrainian reading by syllables, Ukrainian site only):
// content.js, map.js (generated), types.js, art.js. Ambient: no import/export.

/** One word to read. */
interface CHWord {
  /** Unique in the unit: `${station}.${word}` — also the task key. */
  key: string;
  /** The plain word, no stress mark: 'машина'. */
  word: string;
  /** Syllables, the stressed vowel marked with U+0301 (none in one-syllable words): ['ма', 'ши́', 'на']. */
  syl: string[];
  /** Picture (emoji); words without one are only used where no picture is needed. */
  pic?: string;
}

/** A stop of the journey = a station of the exam engine. */
interface CHStation {
  id: string;
  /** City on the map (CH_MAP.cities key). */
  city: string;
  /** 'Київ' */
  cityName: string;
  /** 'Мій дім' */
  theme: string;
  icon: string;
  hue: string;
  words: CHWord[];
}

/** Read the word (split into syllables when `split`, otherwise whole with a «по складах» hint), pick its picture. */
interface CHReadTask extends ExamTaskBase {
  type: 'read';
  key: string;
  word: CHWord;
  /** Right one first; the renderer shuffles. All have a picture. */
  options: CHWord[];
  split: boolean;
}

/** Hear the word (clip), pick how it is written among `options` (right one first). Without a clip/voice: its picture. */
interface CHHearTask extends ExamTaskBase {
  type: 'hear';
  key: string;
  word: CHWord;
  options: string[];
}

/** Build the word from syllable tiles (its syllables + `extra` distractors); clue = picture, the word is spoken after. */
interface CHBuildTask extends ExamTaskBase {
  type: 'build';
  key: string;
  word: CHWord;
  extra: string[];
}

/** A lost letter: the word with one letter missing (`at`), options = letters (right one first). */
interface CHGapTask extends ExamTaskBase {
  type: 'gap';
  key: string;
  word: CHWord;
  /** Index of the missing letter in word.word. */
  at: number;
  options: string[];
}

/** Read a short text, answer the question: `options` are short answers (right one first). */
interface CHStoryTask extends ExamTaskBase {
  type: 'story';
  /** 1–2 short sentences. */
  text: string;
  ask: string;
  options: string[];
}

/** Per-word results in KF.gameData(CHContent.store).w[key]. Numbers only (sync adds both devices' deltas). */
interface CHStat {
  ok: number;
  miss: number;
  /** Right answers in a row (0 after a miss). */
  run: number;
}

interface CHContent extends ExamUnit {
  /** gameData record of the word results (not the engine's own record, which the engine rewrites as a whole). */
  store: string;
  /** The journey in order (= unit.stations order). */
  route: CHStation[];
  /** key → word. */
  words: Record<string, CHWord>;
}

/** Generated by scripts/build-ua-map.mjs (Natural Earth, Ukraine's point of view: Crimea is Ukraine). */
interface CHMap {
  viewBox: string;
  /** SVG path of Ukraine. */
  outline: string;
  /** SVG path of the Dnipro (optional). */
  river?: string;
  /** City id → [x, y] in viewBox units. */
  cities: Record<string, [number, number]>;
}

declare var CH_CONTENT: CHContent;
declare var CH_TYPES: ExamRenderers;
declare var CHArt: ExamArt;
declare var CH_MAP: CHMap;

interface Window {
  CH_CONTENT: CHContent;
  CH_TYPES: ExamRenderers;
  CHArt: ExamArt;
  CH_MAP: CHMap;
}
